#include "3128d8817a11a3ed_creature_children.hpp"
namespace recovered_creature_children{U equipment(U s,Ports&p){p.write(s,p.table());for(U i=0;i<18;++i)p.write(s+4+i*4,0);return s;}U equipment_delete(U s,U flags,Ports&p){p.write(s,p.table());if(flags&1)p.release(s);return s;}U inventory(U s,U id,U mode,Ports&p){p.write(s+16,0);p.write(s+20,0);p.write(s+12,0);p.write(s,id);p.write(s+4,0);U mask=(p.read(s+8)^mode)&1;p.write(s+8,p.read(s+8)^mask);return s;}
U contains(U s,U id,Ports&p){U count=p.read(s+0x924);if(static_cast<std::int32_t>(count)>0){U data=p.read(s+0x920);for(U i=0;i<count;++i)if(p.read(p.read(data+4*i))==id)return 1;}return 0;}
void perception(U s,U id,U a,U b,U c,U d,Ports&p){if(contains(s,id,p))return;U item=p.allocate(8);if(item){U flags=p.byte(item+4)&0xe0;p.write(item,0x7f000000);p.put_byte(item+4,flags);}U bits=((((d&1)<<2)|(c&3))<<1)|(b&1);bits=(bits<<1)|(p.byte(item+4)&0xe0)|(a&1);p.write(item,id);p.put_byte(item+4,bits);U list=s+0x920,capacity=p.read(list+8);if(p.read(list+4)==capacity)p.grow(list,capacity?capacity*2:16);U i=p.read(list+4);p.write(p.read(list)+4*i,item);p.write(list+4,p.read(list+4)+1);}}
